import{esc}from './ui.js';
import{actionIcon}from './action-icons.js';
import{awardArtwork}from './quran-awards-core.js';
import{APP_ANNOUNCEMENT}from './app-release.js';

const gallery=cards=>'<div class="release-gallery"><div class="release-gallery-strip" tabindex="0" aria-label="Новые возможности SALAH">'+cards.join('')+'</div><div class="release-gallery-controls"><button type="button" data-release-prev aria-label="Предыдущая карточка"><img src="./assets/arrow-left.svg" alt=""></button><span data-release-page aria-live="polite">1/'+cards.length+'</span><button type="button" data-release-next aria-label="Следующая карточка"><img src="./assets/arrow-left.svg" alt=""></button></div></div>';
const card=(art,title,text,note='',artClass='')=>'<article class="release-feature"><div class="release-new-art'+(artClass?' '+esc(artClass):'')+'" aria-hidden="true">'+art+'</div><h3>'+esc(title)+'</h3><p>'+esc(text)+'</p>'+(note?'<p class="release-feature-note">'+esc(note)+'</p>':'')+'</article>';
const portrait=(src)=>'<img class="release-reader-portrait" src="./assets/reciters/'+src+'" alt="">';
const artwork=kind=>'<img src="./'+awardArtwork(kind)+'" alt="">';
const screenshot=(name,version=357)=>'<img class="release-screen-picture" src="./assets/updates/'+name+'-'+version+'.png" alt="">';
const readerFigures=readers=>'<div class="release-new-readers release-roundup-readers">'+readers.map(([image,name])=>'<figure>'+portrait(image)+'<figcaption>'+esc(name)+'</figcaption></figure>').join('')+'</div>';
function majorReleaseCards(){return [
 card(readerFigures([['islamsobhi.jpg','Ислам Субхи'],['abdulrahmanalawsi.jpg','Абдуррахман аль-Ауси'],['saadalghamdi.jpg','Саад аль-Гамиди'],['ahmadalajmi.jpg','Ахмад аль-Аджми'],['faresabbad.jpg','Фарис Аббад']]),'13 новых чтецов','Ислам Субхи, Абдуррахман аль-Ауси, Саад аль-Гамиди, Ахмад аль-Аджми и Фарис Аббад.','Коран → Чтецы → Новые. Ещё восемь голосов — на следующей карточке.','release-reciter-art'),
 card(readerFigures([['ahmadalnufais.jpg','Ахмад ан-Нуфайс'],['khalidaljalil.jpg','Халид аль-Джалиль'],['wadeealyamani.jpg','Вади аль-Ямани'],['abdullahkamel.jpg','Абдуллах Камиль'],['haniarrifai.jpg','Хани ар-Рифаи'],['alijaber.jpg','Али Джабир'],['muhammadayyub.jpg','Мухаммад Айюб'],['salahbukhatir.jpg','Салах Бухатир']]),'Ещё восемь голосов','В каталоге 46 чтецов. Избранные остаются под рукой; для недавних добавлений есть фильтр «Новые».','','release-reciter-art'),
 card(screenshot('mushaf'),'Мединский мусхаф','Печатные страницы Корана, цветной таджвид, тёмный и светлый фон. Соседние страницы готовятся заранее для быстрого перелистывания.','Включите чтеца: текущий аят подсвечивается, страницы перелистываются по записи с разметкой.','release-screen-art'),
 card(screenshot('quran-reader'),'Привычный Коран — новое начертание','В карточках аятов — мединское начертание, как в мусхафе. Перевод и настройки размера сохранены.','','release-screen-art'),
 card(screenshot('download'),'Аудио без интернета','Скачивание показывает объём загруженного аудио. Длинные суры не прерываются через прежние 45 секунд, пока данные поступают.','Коран → сура → Aa → Скачать аудио. Запись сохраняется в SALAH. В настройках появилась очистка кэша, включая скачанные суры.','release-screen-art release-download-art'),
 card('<div class="release-shuffle-preview"><div>'+portrait('alafasy.webp')+'<span>'+actionIcon('shuffle')+'</span>'+portrait('yasseraldossari.jpg')+'</div><strong>'+actionIcon('shuffle')+' Перемешать</strong><small>Суры и чтецы · один плейлист</small></div>','Перемешивание чтецов','Случайный плейлист объединяет разные голоса и суры. Следующая запись включается автоматически.','Откройте развёрнутый плеер и нажмите «Перемешать».'),
 card('<div class="release-hours-medals">'+['hours25','hours100','hours1000'].map(artwork).join('')+'</div>','Награды и топы','Награды за часы прослушивания и постоянство. Личные результаты и общий топ — за день, неделю, месяц и всё время.','Подиум сохраняет ровные ступени на разных экранах.'),
 card(screenshot('adhkar'),'Азкары читать удобнее','Настройки чтения стали заметнее. Арабский текст получил мединское начертание; размер и состав текста выбираете вы.','','release-screen-art'),
 card(screenshot('travel',363),'Режим путника','Домашний город и местность в пути — две таблицы на главной. Переключайте их свайпом или кнопками.','Азан, уведомления и виджет следуют выбранной таблице. Настройки → Город и время намаза → Режим путника.','release-screen-art'),
 card(screenshot('qibla-map',363),'Кибла на карте','Приблизьте дом, выберите точку или определите своё место. Золотая линия покажет направление на Каабу.','Значок карты находится внизу справа на экране Киблы. Карта: © OpenStreetMap contributors · openstreetmap.org/copyright.','release-screen-art'),
 card(readerFigures([['yasseraldossari.jpg','Ясир ад-Даусари'],['abdurrahmanalsudais.jpg','Абдуррахман ас-Судайс'],['saudalshuraim.jpg','Сауд аш-Шурайм'],['idrisabkar.png','Идрис Абкар'],['abdulmuhsinalqasim.jpg','Абдульмухсин аль-Касим']]).replace('release-roundup-readers','release-recognition-readers'),'Узнать чтение · бета','Короткий фрагмент помогает найти суру, аят и чтеца. Проверка выполняется на устройстве, без отправки голоса.','Первая база: 69 конкретных записей пяти чтецов. Список доступных сур и ограничения — на экране распознавания.','release-reciter-art'),
 card('<div class="release-tafsir-preview">'+screenshot('mushaf')+'<span>ГОТОВИТСЯ</span><strong>Тафсир ас-Саади<br>Тафсир Ибн Касира</strong></div>','Тафсиры — в подготовке','Планируем добавить толкования ас-Саади и Ибн Касира и дополнительные переводы.','Эти тексты пока недоступны в SALAH: сначала проверяем источники и издания.','release-screen-art')
 ];}

// Known editions have feature-specific pictures. Future public release notes
// retain illustrated cards automatically instead of reverting to a text list.
export function releaseIllustrations(version,changes=[]){
 if(version>=357&&version<=APP_ANNOUNCEMENT.version)return gallery(majorReleaseCards());
 if(version>=351&&version<=356)return gallery([card(screenshot(version===356?'quran-reader':'mushaf'),version===356?'Коран в мединском начертании':'Мусхаф в SALAH',changes[0]||'Печатные страницы Корана в стиле SALAH.','','release-screen-art')]);
 if(version===348||version===349){
 const cards=[
  card('<div class="release-new-readers release-reader-quartet"><figure>'+portrait('ahmadalnufais.jpg')+'<figcaption>Ахмад ан-Нуфайс</figcaption></figure><figure>'+portrait('khalidaljalil.jpg')+'<figcaption>Халид аль-Джалиль</figcaption></figure><figure>'+portrait('wadeealyamani.jpg')+'<figcaption>Вади аль-Ямани</figcaption></figure><figure>'+portrait('abdullahkamel.jpg')+'<figcaption>Абдуллах Камиль</figcaption></figure></div>','Новые чтецы',"Ахмад ан-Нуфайс, Халид аль-Джалиль, Вади аль-Ямани, Абдуллах Камиль.","В каталоге теперь 46 чтецов. Коран → Чтецы.",'release-reciter-art'),
  card('<div class="release-new-readers release-reader-quartet"><figure>'+portrait('haniarrifai.jpg')+'<figcaption>Хани ар-Рифаи</figcaption></figure><figure>'+portrait('alijaber.jpg')+'<figcaption>Али Джабир</figcaption></figure><figure>'+portrait('muhammadayyub.jpg')+'<figcaption>Мухаммад Айюб</figcaption></figure><figure>'+portrait('salahbukhatir.jpg')+'<figcaption>Салах Бухатир</figcaption></figure></div>','Новые чтецы',"Хани ар-Рифаи, Али Джабир, Мухаммад Айюб, Салах Бухатир.","У всех восьмерых — по 114 сур. Для Абдуллаха Камиля разметка аятов пока недоступна.",'release-reciter-art'),
  card('<div class="release-new-readers"><figure>'+portrait('islamsobhi.jpg')+'<figcaption>Ислам Субхи</figcaption></figure><figure>'+portrait('abdulrahmanalawsi.jpg')+'<figcaption>Абдуррахман аль-Ауси</figcaption></figure><figure>'+portrait('saadalghamdi.jpg')+'<figcaption>Саад аль-Гамиди</figcaption></figure><figure>'+portrait('ahmadalajmi.jpg')+'<figcaption>Ахмад аль-Аджми</figcaption></figure><figure>'+portrait('faresabbad.jpg')+'<figcaption>Фарис Аббад</figcaption></figure></div>','Новые чтецы',"Ранее добавлены: Ислам Субхи, Абдуррахман аль-Ауси, Саад аль-Гамиди, Ахмад аль-Аджми, Фарис Аббад.","У Ислама Субхи доступны 109 сур.",'release-reciter-art')
 ];
 if(version===349)cards.unshift(card('<div class="release-discovery-preview"><div class="release-filter-preview"><span>Все 46</span><span class="selected">Новые 13</span><span>Избранные</span><span>Рукъя</span></div><figure>'+portrait('raadalkurdi-v349.png')+'<figcaption>Мухаммад аль-Курди</figcaption></figure></div>','Новые чтецы — в начале','Первые три дня новые голоса появляются сразу после избранных.','Фильтр «Новые» показывает добавления за последние 30 дней. Обновлён портрет Мухаммада аль-Курди.'));
 return gallery(cards);
 }

 if(version===347)return gallery([card('<div class="release-new-readers"><figure>'+portrait('islamsobhi.jpg')+'<figcaption>Ислам Субхи</figcaption></figure><figure>'+portrait('abdulrahmanalawsi.jpg')+'<figcaption>Абдуррахман аль-Ауси</figcaption></figure><figure>'+portrait('saadalghamdi.jpg')+'<figcaption>Саад аль-Гамиди</figcaption></figure><figure>'+portrait('ahmadalajmi.jpg')+'<figcaption>Ахмад аль-Аджми</figcaption></figure><figure>'+portrait('faresabbad.jpg')+'<figcaption>Фарис Аббад</figcaption></figure></div>','Новые чтецы','Ислам Субхи, Абдуррахман аль-Ауси, Саад аль-Гамиди, Ахмад аль-Аджми и Фарис Аббад — теперь в SALAH.','Коран → Чтецы. У Ислама Субхи доступны 109 сур, у остальных — по 114.','release-reciter-art')]);

 if(version===346)return gallery([card('<svg viewBox="0 0 140 140" fill="none"><circle cx="70" cy="70" r="46" stroke="currentColor" stroke-width="2"/><path d="M58 48l34 22-34 22zM106 27v22H84" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/><path d="M105 48a42 42 0 0 0-70-10" stroke="currentColor" stroke-width="2"/></svg>','Продолжение без зависания','Если загрузка аята остановилась, плеер пробует резервный источник и сохраняет место.','Если запись недоступна, можно повторить воспроизведение.')]);

 if(version===345)return gallery([card('<svg viewBox="0 0 160 140" fill="none"><rect x="15" y="48" width="38" height="76" rx="8" stroke="#c2cbd8" stroke-width="2"/><rect x="61" y="24" width="38" height="100" rx="8" stroke="#d8be88" stroke-width="2"/><rect x="107" y="64" width="38" height="60" rx="8" stroke="#bf926c" stroke-width="2"/><text x="34" y="74" text-anchor="middle" fill="#c2cbd8" font-size="18">2</text><text x="80" y="51" text-anchor="middle" fill="#d8be88" font-size="21">1</text><text x="126" y="90" text-anchor="middle" fill="#bf926c" font-size="18">3</text></svg>','Единый подиум','Во всех периодах — общее основание и ровные ступени. Длинные имена больше не меняют их высоту.','Время на подиуме: часы:минуты:секунды.')]);

 if(version===344)return gallery([card('<svg viewBox="0 0 140 140" fill="none"><rect x="24" y="24" width="92" height="92" rx="26" stroke="currentColor" stroke-width="2"/><path d="M49 43l42 27-42 27z" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/></svg>','Ровный значок плеера','Треугольник воспроизведения расположен по центру кнопки — в маленьком и полном плеере.')]);

 if(version===343)return gallery([card('<svg viewBox="0 0 160 140" fill="none"><rect x="15" y="62" width="38" height="62" rx="8" stroke="#c2cbd8" stroke-width="2"/><rect x="61" y="24" width="38" height="100" rx="8" stroke="#d8be88" stroke-width="2"/><rect x="107" y="76" width="38" height="48" rx="8" stroke="#bf926c" stroke-width="2"/><text x="34" y="88" text-anchor="middle" fill="#c2cbd8" font-family="Georgia,serif" font-size="21">2</text><text x="80" y="55" text-anchor="middle" fill="#d8be88" font-family="Georgia,serif" font-size="25">1</text><text x="126" y="103" text-anchor="middle" fill="#bf926c" font-family="Georgia,serif" font-size="21">3</text></svg>','Первое место — выше','Подиум сохраняет правильную высоту, даже когда имя или время занимают несколько строк.','Результаты и места слушателей не изменены.'),card('<svg viewBox="0 0 140 140" fill="none"><path d="M70 120s37-38 37-65a37 37 0 0 0-74 0c0 27 37 65 37 65Z" stroke="currentColor" stroke-width="2"/><circle cx="70" cy="54" r="13" stroke="currentColor" stroke-width="2"/></svg>','Поиск местоположения','Определение города стало устойчивее при слабом GPS-сигнале. Сообщения подскажут, если нет координат или связи.','Исправление разрешений Android требует обновления приложения через Google Play.')]);

 if(version===342)return gallery([card('<svg viewBox="0 0 150 140" fill="none"><rect x="24" y="25" width="102" height="96" rx="14" stroke="currentColor" stroke-width="2"/><path d="M24 52h102M48 16v20M102 16v20" stroke="currentColor" stroke-width="2"/><text x="75" y="88" text-anchor="middle" fill="currentColor" font-family="Georgia,serif" font-size="32">30</text><text x="75" y="108" text-anchor="middle" fill="currentColor" font-size="10">НОЯБРЬ</text></svg>','Ноябрь в календаре Тюмени','Месяц добавлен по присланной таблице: первое время Асра и Аср в мечетях сохранены отдельно.','Времена перенесены из таблицы 2025 года; дни недели указаны для ноября 2026.'),card('<div class="release-total-preview"><div><span>МОЙ ТОП</span><strong>Ваше время</strong></div><div><span>ТОП SALAH</span><strong>Вместе прослушали</strong></div></div>','Компактнее и точнее','Счётчик в топах занимает меньше места — подиум виден выше.','Повторный учёт старых минут в месячном итоге исправлен.')]);

 if(![339,340,341].includes(version)){
  if(!Number.isSafeInteger(version)||version<=341||!Array.isArray(changes))return '';
  const safe=changes.filter(x=>typeof x==='string'&&x.trim()&&x.length<=240&&!/владел|админ|owner|admin/iu.test(x)).slice(0,8);
  return safe.length?gallery(safe.map(text=>card(actionIcon(/чтец|аудио|плеер/iu.test(text)?'play':'book'),'Что изменилось',text))):'';
 }
 const cards=[
  card('<div class="release-hours-medals">'+['hours25','hours100','hours1000'].map(artwork).join('')+'</div>','Новые награды','За 25, 50, 100, 250, 500, 1 000 и 5 000 часов прослушивания Корана.','Полученные награды остаются в вашем аккаунте.'),
  card('<div class="release-shuffle-preview"><div>'+portrait('alafasy.webp')+'<span>'+actionIcon('shuffle')+'</span>'+portrait('muhammadalluhaidan.jpg')+'</div><strong>'+actionIcon('shuffle')+' Перемешать</strong><small>Суры и чтецы · один плейлист</small></div>','Случайный плейлист','Нажмите «Перемешать» в развёрнутом плеере: SALAH соберёт плейлист сур и чтецов.','Следующая запись включается автоматически.'),
  card('<div class="release-total-preview"><div><span>МОЙ ТОП</span><strong>Ваше время</strong></div><div><span>ТОП SALAH</span><strong>Вместе прослушали</strong></div></div>','Время в топах','В «Мой топ» — ваше время прослушивания. В «Топ SALAH» — общее время участников.','Общий счётчик обновляется после сохранения статистики.')
 ];
 if(version>=340)cards.push(card('<div class="release-city-pair"><figure><img src="./assets/updates/kaspiysk-v1.webp" alt="" loading="lazy"><figcaption>Каспийск</figcaption></figure><figure><img src="./assets/updates/kazan-v1.webp" alt="" loading="lazy"><figcaption>Казань</figcaption></figure></div>','Новые городские обои','Каспийск и Казань: дневной свет, вечернее освещение и плавный переход к ночи.','Настройки → Оформление и атмосфера → Обои.'));
 cards.push(
  card('<div class="release-play-preview">'+actionIcon('play')+'<span>Google Play</span><small>ЗАКРЫТЫЙ ТЕСТ</small></div>','SALAH в Google Play','Закрытая тестовая версия одобрена и опубликована для приглашённых тестировщиков.','Общий выпуск для всех пользователей готовится.'),
  card('<div class="release-support-preview"><span>Поддержать SALAH</span><strong>от 150 ₽</strong><small>в месяц · добровольно</small></div>','Готовим добровольную поддержку','Скоро появится возможность поддержать развитие SALAH ежемесячной подпиской.','Оплата пока отключена. Все функции приложения остаются бесплатными.'),
  card('<div class="release-instagram-preview"><svg viewBox="0 0 64 64" fill="none"><rect x="10" y="10" width="44" height="44" rx="13" stroke="currentColor" stroke-width="2.5"/><circle cx="32" cy="32" r="11" stroke="currentColor" stroke-width="2.5"/><circle cx="46" cy="18" r="3" fill="currentColor"/></svg><span>SALAH · Saadi</span></div>','Мы в Instagram','В приложении появились ссылки на Instagram SALAH и страницу основателя Saadi.','Ищите их в разделе «О приложении».')
 );
 return gallery(cards);
}
